 *  - gallery tab titles (.elementor-tab-title) in their inactive state
 * These rules pin explicit high-contrast colors on exactly those
 * surfaces. They do not restyle branding: buttons, menus and headings
 * outside the form/tab contexts are untouched. (The header GET A QUOTE
 * button's white-on-brand pairing is handled separately once its exact
 * fg/bg pair is read from the audit detail.)
 */
.elementor-field,
input.elementor-field,
textarea.elementor-field,
select.elementor-field {
  color: #111111;
}
.elementor-form .elementor-field-type-html h3,
.elementor-form .elementor-field-type-html {
  color: #111111;
}
.elementor-tab-title {
  color: #222222;
}
.elementor-tab-title.elementor-active {
  color: #111111;
}

