/* MT forms UX attributes — v1.0.0 (2026-11-11). BUILD ONLY.
 * Audit H8: ZERO autocomplete / inputmode / type="tel" on any route.
 * Why JS attribute-setting is safe here: it changes no field name, value,
 * validation or submission behaviour — it only (a) tells mobile browsers
 * which keyboard/autofill to offer and (b) turns the Phone text inputs into
 * type="tel" (same value semantics; Elementor/Woo do not pattern-validate
 * these fields). Fields are matched by PLACEHOLDER TEXT + name patterns,
 * never by id: the quote form is served 3x per page with DUPLICATED ids
 * (form-field-name etc.), and the two form instances even swap the
 * message/address field names — placeholder is the only stable key.
 * Idempotent (data-mt-forms marker). Vanilla, ES2019. */
(function () {
  "use strict";
  function set(el, attrs) {
    if (!el || el.getAttribute("data-mt-forms")) return;
    for (var k in attrs) {
