    byPlaceholder(document, "company", { autocomplete: "organization" });
    byPlaceholder(document, "email", { autocomplete: "email", inputmode: "email" });
    byPlaceholder(document, "phone", { type: "tel", autocomplete: "tel", inputmode: "tel" });
    byPlaceholder(document, "project address", { autocomplete: "street-address" });
    /* Newsletter (Zoho) email box: name="Email", placeholder "Email Address" —
       attributes only, type left untouched (third-party handler). */
    byPlaceholder(document, "email address", { autocomplete: "email", inputmode: "email" });
    /* Any remaining Elementor email/phone fields missed by placeholder match */
    els = document.querySelectorAll('input[name="form_fields[email]"]');
    for (i = 0; i < els.length; i++) set(els[i], { autocomplete: "email", inputmode: "email" });
