      billing_first_name: { autocomplete: "given-name" },
      billing_last_name: { autocomplete: "family-name" },
      billing_company: { autocomplete: "organization" },
      billing_email: { autocomplete: "email", inputmode: "email" },
      billing_phone: { type: "tel", autocomplete: "tel", inputmode: "tel" },
      billing_address_1: { autocomplete: "address-line1" },
      billing_address_2: { autocomplete: "address-line2" },
      billing_city: { autocomplete: "address-level2" },
      billing_postcode: { autocomplete: "postal-code", inputmode: "numeric" },
      shipping_first_name: { autocomplete: "given-name" },
      shipping_last_name: { autocomplete: "family-name" },
      shipping_company: { autocomplete: "organization" },
      shipping_address_1: { autocomplete: "address-line1" },
      shipping_address_2: { autocomplete: "address-line2" },
      shipping_city: { autocomplete: "address-level2" },
      shipping_postcode: { autocomplete: "postal-code", inputmode: "numeric" }
