(function () {
    'use strict';
    var CFG = window.MT_MEASURE_CFG || {};
    window.dataLayer = window.dataLayer || [];
    var QA = (function () {
        try {
            var qs = new URLSearchParams(window.location.search);
            if (qs.get('mt_qa') === '1') { window.localStorage.setItem('mt_qa', '1'); }
            if (qs.get('mt_qa') === '0') { window.localStorage.removeItem('mt_qa'); }
            if (window.localStorage.getItem('mt_qa') === '1') { return 1; }
        } catch (e) { }
