        if (closest(f, '.elementor-location-footer') || closest(f, '[data-elementor-type="footer"]') || closest(f, 'footer')) { return 'footer'; }
        var pt = CFG.page_type || '';
        if (pt === 'product') { return 'product-location'; }
        if (pt === 'account') { return 'consultation'; }
        if (pt === 'quote') { return 'quote-page'; }
        if (pt === 'contact') { return 'contact'; }
        if (pt === 'home') { return 'hero'; }
        return 'unknown';
    }
