        if (/verify|verification|challenge|robot|altcha|proof of work|pow/.test(t)) { return 'pow'; }
        if (/required|invalid|please fill|must be|enter a valid/.test(t)) { return 'validation'; }
        if (/server|try again|failed|error occurred|unable/.test(t)) { return 'server'; }
        return 'other';
    }
