        for (var k in ft) { params[k] = ft[k]; }
        push('quote_form_submit', params);
        if (surface === 'popup') {
            push('popup_submit', { surface: 'popup', trigger_source: 'popup_form' });
        }
        try {
            var raw = window.sessionStorage.getItem('mt_pending_submit');
            if (raw) {
                var p = JSON.parse(raw);
                p.fired = true;
                window.sessionStorage.setItem('mt_pending_submit', JSON.stringify(p));
            }
        } catch (e) { }
    }
    function onFormError(f, text) {
        push('quote_form_error', {
            surface: surfaceOf(f),
            form_id: hiddenVal(f, 'form_id'),
            error_class: errorClass(text)
        });
    }
    function registerForm(f) {
        if (registeredForms.has(f)) { return; }
        registeredForms.add(f);
        if (viewObserver) {
            viewObserver.observe(f);
