            seenView.add(f);
            push('quote_form_view', { surface: surfaceOf(f), form_id: hiddenVal(f, 'form_id') });
        }
        var start = function () {
            if (seenStart.has(f)) { return; }
            seenStart.add(f);
            lastForm = f;
            push('quote_form_start', { surface: surfaceOf(f), form_id: hiddenVal(f, 'form_id') });
        };
        f.addEventListener('input', start, { passive: true });
        f.addEventListener('focusin', start);
        f.addEventListener('submit', function () {
            lastForm = f;
            try {
                window.sessionStorage.setItem('mt_pending_submit', JSON.stringify({
                    surface: surfaceOf(f),
                    form_id: hiddenVal(f, 'form_id'),
                    page_path: window.location.pathname,
                    ts: Date.now(),
                    fired: false
                }));
            } catch (e) { }
        });
        if ('MutationObserver' in window) {
            var mo = new MutationObserver(function (muts) {
                for (var i = 0; i < muts.length; i++) {
