            });
        } catch (e) { }
    }
    function initThankYouFallback() {
        if (window.location.pathname.replace(/\/+$/, '') !== '/thank-you') { return; }
        try {
            var raw = window.sessionStorage.getItem('mt_pending_submit');
            if (!raw) { return; }
            var p = JSON.parse(raw);
