    }
    var lastVideoAt = {};
    function ytIdFrom(el) {
        if (!el) { return null; }
        var cand = [el, closest(el, '[data-video-id]'), closest(el, '[data-youtube-id]')];
        for (var i = 0; i < cand.length; i++) {
            var c = cand[i];
            if (!c || !c.getAttribute) { continue; }
            var d = c.getAttribute('data-video-id') || c.getAttribute('data-youtube-id');
            if (d) { return d; }
        }
        var a = closest(el, 'a[href]');
        if (a) {
            var m = (a.getAttribute('href') || '').match(/(?:[?&]v=|youtu\.be\/|embed\/)([\w-]{6,})/);
            if (m) { return m[1]; }
        }
        try {
            var img = el.querySelector ? el.querySelector('img') : null;
            if (img) {
                var m2 = (img.getAttribute('src') || '').match(/\/vi\/([\w-]{6,})\//);
                if (m2) { return m2[1]; }
            }
        } catch (e) { }
        return null;
    }
    function onDocumentClick(e) {
