        if (lb) { rememberLightboxTrigger(lb); }
        var a = closest(t, 'a[href]');
        if (a) {
            var href = a.getAttribute('href') || '';
            if (href.indexOf('tel:') === 0) {
                var placement = 'body';
                if (closest(a, 'header') || closest(a, '[data-elementor-type="header"]')) { placement = 'header'; }
                else if (closest(a, 'footer') || closest(a, '[data-elementor-type="footer"]') || closest(a, '.elementor-location-footer')) { placement = 'footer'; }
