    }
    var lastPopupAt = {};
    var watchedLayers = new WeakSet();
    function popupIdOf(node) {
        try {
            var doc = node.querySelector ? node.querySelector('[data-elementor-type="popup"]') : null;
            var cls = doc ? (doc.getAttribute('class') || '') : (node.getAttribute('class') || '');
            var m = cls.match(/elementor-(\d+)/);
            if (m) { return m[1]; }
            var idm = (node.getAttribute('id') || '').match(/(\d+)/);
            return idm ? idm[1] : 'unknown';
        } catch (e) { return 'unknown'; }
    }
    function firePopupOpen(node) {
        var id = popupIdOf(node);
        var now = Date.now();
        if (lastPopupAt[id] && (now - lastPopupAt[id]) < 1500) { return; }
        lastPopupAt[id] = now;
        push('popup_open', { popup_id: id, trigger_source: 'elementor' });
    }
    var pendingProjectId = '';
    var pendingProjectAt = 0;
    function rememberLightboxTrigger(el) {
        pendingProjectAt = Date.now();
        pendingProjectId = '';
        try {
            var a = el.tagName === 'A' ? el : closest(el, 'a[href]');
