            if (img) {
                var m = (img.getAttribute('class') || '').match(/wp-image-(\d+)/);
                if (m) { pendingProjectId = m[1]; return; }
            }
            if (a) {
                var href = a.getAttribute('href') || '';
                var seg = href.split('?')[0].replace(/\/+$/, '').split('/');
                var last = seg[seg.length - 1] || '';
                if (last && !/\.(jpe?g|png|webp|gif)$/i.test(last)) { pendingProjectId = last; }
            }
        } catch (e) { }
    }
    var lightboxWasVisible = false;
    function fireLightboxOpen(node) {
        var pid = '';
        if (pendingProjectId && (Date.now() - pendingProjectAt) < 5000) { pid = pendingProjectId; }
        if (!pid) {
            try {
                var img = node.querySelector ? node.querySelector('img') : null;
                if (img) {
                    var m = (img.getAttribute('class') || '').match(/wp-image-(\d+)/);
                    if (m) { pid = m[1]; }
                }
            } catch (e) { }
        }
        push('gallery_lightbox_open', { project_id: pid || 'unknown' });
    }
    function isVisible(node) {
        try {
            var cs = window.getComputedStyle(node);
            return cs.display !== 'none' && cs.visibility !== 'hidden';
        } catch (e) { return false; }
    }
    function watchLayer(node) {
        if (!node || watchedLayers.has(node)) { return; }
        watchedLayers.add(node);
