        try {
            var nodes = (root || document).querySelectorAll('.elementor-popup-modal, .elementor-lightbox');
            for (var i = 0; i < nodes.length; i++) { watchLayer(nodes[i]); }
        } catch (e) { }
    }
    function initPopupBridge() {
        if (!window.jQuery) { return; }
        try {
            window.jQuery(document).on('elementor/popup/show', function (evt, id) {
                var key = id ? String(id) : 'unknown';
                var now = Date.now();
                if (lastPopupAt[key] && (now - lastPopupAt[key]) < 1500) { return; }
                lastPopupAt[key] = now;
                push('popup_open', { popup_id: key, trigger_source: 'elementor' });
            });
        } catch (e) { }
    }
    function init() {
        scanForms(document);
        scanLayers(document);
