(function () {
  function humanize(s) {
    return (s || '').replace(/[-_]+/g, ' ').replace(/\s+/g, ' ').trim();
  }
  function run() {
    // 1. Form field labels.
    var fields = document.querySelectorAll('input, textarea, select');
    for (var i = 0; i < fields.length; i++) {
      var f = fields[i];
      if (f.type === 'hidden' || f.type === 'submit' || f.type === 'button') continue;
      if (f.getAttribute('aria-label') || f.getAttribute('aria-labelledby')) continue;
      if (f.id && document.querySelector('label[for="' + CSS.escape(f.id) + '"]')) continue;
      if (f.closest && f.closest('label')) continue;
      var label = f.getAttribute('placeholder') || '';
      if (!label && f.closest) {
        var group = f.closest('.elementor-field-group, .form-group, p, div');
        var gl = group ? group.querySelector('.elementor-field-label, label') : null;
        if (gl) label = gl.textContent || '';
      }
      if (!label) label = humanize(f.name || f.type || 'field');
      if (label) f.setAttribute('aria-label', label.replace(/\s+/g, ' ').trim());
    }
    // 2. Main landmark + skip-link target.
    var root = document.querySelector('[data-elementor-type="wp-page"], [data-elementor-type="single-page"], #content');
    if (!document.querySelector('main, [role="main"]') && root) {
      root.setAttribute('role', 'main');
    }
    if (!document.getElementById('content') && root) {
      root.setAttribute('id', 'content');
      root.setAttribute('tabindex', '-1');
    }
    // 3. Descriptive names for text-less links.
    var links = document.querySelectorAll('a');
    for (var j = 0; j < links.length; j++) {
      var a = links[j];
      if (a.getAttribute('aria-label') || a.getAttribute('title')) continue;
      if ((a.textContent || '').replace(/\s+/g, '')) continue;
      var img = a.querySelector('img');
      var name = img ? (img.getAttribute('alt') || '') : '';
      if (!name) {
        var icon = a.querySelector('[class*="social-icon-"], [class*="icon-"]');
        if (icon) {
          var cls = icon.getAttribute('class') || '';
          var mm = cls.match(/(?:social-icon-|icon-)([a-z0-9]+)/);
          if (mm) name = mm[1];
        }
      }
      if (!name) {
        var href = a.getAttribute('href') || '';
        try {
          var u = new URL(href, window.location.origin);
          if (u.hostname && u.hostname !== window.location.hostname) {
            name = u.hostname.replace(/^www\./, '').split('.')[0];
          } else {
            var seg = u.pathname.split('/').filter(Boolean).pop() || '';
            name = humanize(decodeURIComponent(seg));
          }
        } catch (e) { name = ''; }
      }
      if (name) a.setAttribute('aria-label', name.charAt(0).toUpperCase() + name.slice(1));
    }
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', run);
  } else { run(); }
  window.addEventListener('load', function () { setTimeout(run, 1200); });
})();

(function () {
  var done = false;
  function restore() {
    if (done) return;
    done = true;
    var tags = document.querySelectorAll('script[type="text/plain"][data-mtl-delay]');
    for (var i = 0; i < tags.length; i++) {
      var s = document.createElement('script');
      s.src = tags[i].getAttribute('data-mtl-src');
      s.async = false;
      tags[i].parentNode.insertBefore(s, tags[i]);
      tags[i].parentNode.removeChild(tags[i]);
    }
  }
  var events = ['pointerdown', 'keydown', 'touchstart', 'scroll', 'wheel', 'mousemove'];
  for (var j = 0; j < events.length; j++) {
    window.addEventListener(events[j], restore, { once: true, passive: true });
  }
  window.addEventListener('load', function () { setTimeout(restore, 8000); });
  setTimeout(restore, 15000); // Absolute fail-safe.
})();
